@charset "UTF-8";

/* ----------------------------------------
  reset
---------------------------------------- */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}
ul {
  list-style: none;
}
a {
  color: inherit;
  text-decoration: none;
}
img {
  max-width: 100%;
  vertical-align: bottom;
}

/* ----------------------------------------
  body（全体設定）
---------------------------------------- */
body {
  margin: 0;
  background-color: #f2f2f2;
  font-family: sans-serif;
}


/* ----------------------------------------
  layout
---------------------------------------- */
.container {
  width: 800px;
  margin: 0 auto;
  background-color: #ffffff;
}


/* ----------------------------------------
  header（背景画像付き）
---------------------------------------- */
header {
  position: relative;
  height: 320px;
  background-image: url("https://images.unsplash.com/photo-1501004318641-b39e6451bec6?q=80&w=1600&auto=format&fit=crop");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
  color: #ffffff;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
}

/* オーバーレイ */
header::before {
  content: "";
  position: absolute;
  inset: 0;
  background-color: rgba(27, 67, 50, 0.6); /* 深緑の半透明 */
}
  header h1,
  header p {
    position: relative; /* オーバーレイより前に出す */
  }
  header h1 {
    font-size: 36px;
    margin-bottom: 10px;
  }


/* ------------------------------
   main
------------------------------ */
main {
  padding: 40px;
}
section {
  margin-bottom: 60px;
}
  section h2 {
    margin-bottom: 20px;
    border-bottom: 2px solid #2d6a4f;
    padding-bottom: 10px;
    color: #1b4332;
  }
  section p {
    line-height: 1.8;
    margin-bottom: 15px;
  }
  ul {
    padding-left: 20px;
  }
  li {
    margin-bottom: 10px;
  }
.button {
  display: inline-block;
  background-color: #40916c;
  color: #ffffff;
  padding: 10px 20px;
  text-decoration: none;
  border-radius: 5px;
  transition: 0.3s;
}
  .button:hover {
    background-color: #2d6a4f;
  }

/* ----------------------------------------
  table（メニュー）
---------------------------------------- */
table {
  width: 100%;
  border-collapse: collapse;
}
  thead {
    background-color: #2d6a4f;
    color: #ffffff;
  }
  th, td {
    padding: 15px;
    border-bottom: 1px solid #dddddd;
  }
  th {
    text-align: left;
  }
  td:last-child {
    text-align: right; /* 価格右寄せ */
  }

  /* ホバー効果 */
  tbody tr:hover {
    background-color: #f1f8f4;
  }

/* ----------------------------------------
  footer
---------------------------------------- */
footer {
  background-color: #1b4332;
  color: #ffffff;
  text-align: center;
  padding: 20px;
}

